/** A short reading passage with test-style questions, with niqqud like the real test. */
data class Passage(val id: String, val title: String, val paragraphs: List<String>, val questions: List<RQ>)

/** A reading question. The correct answer is always written first here; it is shuffled when shown. */
data class RQ(val q: String, val right: String, val wrong: List<String>, val why: String)

